fragment.source:
// Solar Flare: a translucent star of glowing filament contours wrapped in flames, coloured by one
// temperature ramp. The flames start inside the limb and burn outward over the edge, so the fire sits
// on the star. A raised hand lets the fire on its side climb toward it.
float sfH(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float sfV(vec2 p){
 vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
 return mix(mix(sfH(i),sfH(i+vec2(1.0,0.0)),f.x),mix(sfH(i+vec2(0.0,1.0)),sfH(i+vec2(1.0,1.0)),f.x),f.y);
}
float sfH3(vec3 p){p=fract(p*vec3(.1031,.1030,.0973));p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z);}
float sfV3(vec3 p){
 vec3 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);
 return mix(mix(mix(sfH3(i),sfH3(i+vec3(1,0,0)),f.x),mix(sfH3(i+vec3(0,1,0)),sfH3(i+vec3(1,1,0)),f.x),f.y),
            mix(mix(sfH3(i+vec3(0,0,1)),sfH3(i+vec3(1,0,1)),f.x),mix(sfH3(i+vec3(0,1,1)),sfH3(i+vec3(1,1,1)),f.x),f.y),f.z);
}
// Flame noise over (direction on the circle, height - time): isotropic around the star.
float sfNoise(vec3 q){
 float sx=sin(q.x),cx=cos(q.x),sy=sin(q.y),cy=cos(q.y),sz=sin(q.z),cz=cos(q.z);
 float n=sx*sy+sy*cz+sz*cx;
 float s2x=2.0*sx*cx,c2x=1.0-2.0*sx*sx,s2y=2.0*sy*cy,c2y=1.0-2.0*sy*sy,s2z=2.0*sz*cz,c2z=1.0-2.0*sz*sz;
 n+=.45*(s2x*s2y+s2y*c2z+s2z*c2x);
 float s4x=2.0*s2x*c2x,c4x=1.0-2.0*s2x*s2x,s4y=2.0*s2y*c2y,s4z=2.0*s2z*c2z,c4z=1.0-2.0*s2z*s2z;
 return n+.2*(s4x*s4y+s4y*c4z+s4z*c4x);
}
// Plasma field on the star; its evenly spaced contours are the abstract filament lines.
float sfField(vec3 pos,float t){
 vec3 q=pos*(4.4+uParam_detail*3.6)+vec3(t*.45,-t*.28,t*.2);
 q+=uParam_corona*.55*sin(q.yzx*.65+vec3(.0,t*.13,.8));
 return sfNoise(q);
}
float sfLines(float n,float t,float w){
 float f=sin(n*4.2+t*.35);
 return w/(w+f*f);
}
// Blackbody-like ramp: deep tint, gold, then white heat; brighter as it gets hotter.
vec3 sfRamp(float T,vec3 tint){
 T=clamp(T,0.0,1.4);
 vec3 c=tint*smoothstep(.0,.4,T);
 c=mix(c,vec3(1.0,.55,.12),smoothstep(.38,.72,T));
 c=mix(c,vec3(1.0,.88,.62),smoothstep(.75,1.05,T));
 return c*(.1+1.5*T*T);
}
// Flame noise coordinate at height h above the limb (negative over the disk) in direction pd.
vec3 sfFireQ(vec2 pd,float h,float t,float surge,float warp){
 vec3 q=vec3(pd*7.0,h*4.0-t*(1.15+1.3*surge));
 q.xy+=vec2(-pd.y,pd.x)*(sfV3(q*vec3(.5,.5,.8)+vec3(0.0,0.0,t*.25))-.5)*warp*(1.4+6.0*max(h,0.0));
 return q;
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 p=(2.0*fragCoord-iResolution.xy)/max(min(iResolution.x,iResolution.y),1.0);
 float aspect=iResolution.x/max(iResolution.y,1.0);
 float t=vrchPhase_speed();
 float limb=uParam_radius*.78;
 float r=length(p),a=atan(p.y,p.x);
 vec3 tint=uParam_tint.rgb;
 float warp=.6+1.6*uParam_corona;
 // Hands: each raised hand lets the fire on its side climb toward it (aimed from the chest).
 float lp=smoothstep(.02,.2,uParam_left_y),rp=smoothstep(.02,.2,uParam_right_y);
 vec2 lh=vec2((uParam_left_x-.5)*2.0*min(aspect,1.6),(uParam_left_y-.5)*2.0);
 vec2 rh=vec2((uParam_right_x-.5)*2.0*min(aspect,1.6),(uParam_right_y-.5)*2.0);
 vec2 chest=vec2(0.0,-.35);
 vec2 d1=normalize(lh-chest+vec2(1e-4)),d2=normalize(rh-chest+vec2(1e-4));
 float surge=clamp(uParam_accent+max(uParam_motion-.3,0.0)*1.4,0.0,1.4);
 float h1=lp*(.1+.7*smoothstep(.35,.95,uParam_left_y))*uParam_lift;
 float h2=rp*(.1+.7*smoothstep(.35,.95,uParam_right_y))*uParam_lift;
 vec2 pd=p/max(r,1e-4);
 float g1=exp(-(1.0-dot(pd,d1))*14.0),g2=exp(-(1.0-dot(pd,d2))*14.0);
 float handH=h1*g1+h2*g2;
 float T=0.0;
 // The plasma boundary wobbles with the flow, so the star never shows a clean circular outline.
 float Le=limb*(1.0+.11*(sfV(pd*4.0+vec2(t*.13,-t*.05))-.5)+.06*(sfV(pd*11.0+vec2(-t*.21,t*.17))-.5));
 // Flames first: one fire around and across the star. Height is measured from the limb and is
 // negative over the disk, where the same tongues lick across the visible surface toward the edge,
 // so the fire sits on the star rather than behind it.
 float fireT=0.0,fireMask=0.0;
 float h=r-limb;
 // Wild by default: a few tall tongues wander round the star between lower flames;
 // their allowed height grows where a hand pulls.
 float tall=sfV(pd*2.6+vec2(t*.11,-t*.07)),tall2=tall*tall;
 float H=.11+.06*sfV(pd*6.0+vec2(t*.2,0.0))+.32*tall2*tall+handH*(1.0+.6*surge)+.07*surge+limb*.1;
 // The flame field is at most 1: past 1.83 H neither a flame nor its edge glow can reach.
 if(r>limb*.5&&h<H*1.83){
  // The flame field is smooth: the coarse stage samples it at 2x2 block centres; interpolate.
  vec2 g=(fragCoord-1.0)*.5,gi=floor(g),gw=fract(g);
  vec2 lo=vec2(.5),hi=iResolution.xy-.5;
  float f00=vrchCoarseData(clamp(gi*2.0+.5,lo,hi)).x,f10=vrchCoarseData(clamp(gi*2.0+vec2(2.5,.5),lo,hi)).x;
  float f01=vrchCoarseData(clamp(gi*2.0+vec2(.5,2.5),lo,hi)).x,f11=vrchCoarseData(clamp(gi*2.0+2.5,lo,hi)).x;
  float f=mix(mix(f00,f10,gw.x),mix(f01,f11,gw.x),gw.y);
  // Over the disk the tongues thin out the further they reach in from the edge.
  float inside=max(-h,0.0)/limb;
  float v=f*1.8-max(h,0.0)/H*.8-.34-inside*2.2;
  float fire=clamp(v*2.0,0.0,1.0);
  fire*=fire;
  float edge=exp(-abs(v)*14.0);
  // Over the disk the flames thin out toward the centre, where the surface faces the viewer.
  float onDisk=smoothstep(limb*.5,limb*.95,r);
  fireMask=fire*onDisk;
  float over=mix(.45,1.0,smoothstep(limb*.92,limb*1.04,r));
  fireT=(fire*(.55+.4*f)+edge*.22*(1.0-smoothstep(.0,H*1.4,max(h,0.0))))*onDisk*over;
 }
 if(r<Le*1.15){
  // Sphere surface in view space; the star turns under the filament lines.
  float z=sqrt(max(Le*Le-r*r,0.0))/Le;
  vec2 pf=p/max(r,1e-4)*min(r,Le);
  vec3 n=vec3(pf/Le,z);
  // Translucent star: filament contours at three depths, in the same temperature ramp as the
  // flames. Lines run hot (gold to white), the plasma between them is cool and dark.
  float Rq=uParam_radius*1.35;
  mat2 yaw=mat2(cos(t*.12),-sin(t*.12),sin(t*.12),cos(t*.12));
  float tl=.18+uParam_corona*.12;mat2 tilt=mat2(cos(tl),-sin(tl),sin(tl),cos(tl));
  // The middle layer is a flat slice through the star: its lines keep an even spacing all the way
  // out and simply fade instead of crowding into a rim.
  vec3 f1=n*Rq,f2=vec3(n.xy,-n.z)*Rq,f3=vec3(p/Le,0.0)*Rq*1.18;
  f1.xz=yaw*f1.xz;f1.yz=tilt*f1.yz;f2.xz=yaw*f2.xz;f2.yz=tilt*f2.yz;f3.xz=yaw*f3.xz;f3.yz=tilt*f3.yz;
  float lw=.035+.05*(1.0-uParam_light);
  float n1=sfField(f1,t),n2=sfField(f2,t),n3=sfField(f3,t);
  float l1=sfLines(n1,t,lw),l2=sfLines(n2,t,lw),l3=sfLines(n3,t,lw);
  float mu=z;
  float rr=r/Le;
  float fill=smoothstep(1.0,.5,rr);
  T=(.24+.1*smoothstep(-.6,1.0,n3))*fill;
  float keep=smoothstep(.15,.6,mu)*step(rr,1.0);
  // Filament lines catch fire where a flame crosses them.
  float burn=1.0+.6*fireMask;
  T+=(l1*(.5+.25*uParam_light)*(.75+.25*mu)+l2*.14*(1.0-mu*.5))*keep*burn;
  T+=l3*(.24+.24*(1.0-keep))*smoothstep(1.13,.8,rr)*burn;
  // The side facing a raised hand runs hotter.
  // Both warm-ups fade out with the plasma, so they never show the region's circular bound.
  float body=smoothstep(1.1,.8,rr);
  T+=(.18*(lp*g1+rp*g2)*smoothstep(.4,1.0,r/limb)+.1*surge)*body;
 }
 // Flames glow over the disk (added, so the lines show through them) and beyond it.
 T+=fireT;
 if(r>limb*.85){
  // Soft corona and fine radial streamers, faded in across the disk's outer band.
  float ho=max(r-limb,0.0);
  float streak=sfV(vec2(a*14.0,ho*1.5-t*.2))*sfV(vec2((a+6.2832)*14.0,ho*1.5-t*.2))*1.6;
  float corona=(exp(-ho/(.06+.05*uParam_corona))*(.3+.2*streak)+exp(-ho/.3)*.06)*smoothstep(limb*.85,limb*1.06,r);
  T=max(T,corona*.36);
 }
 vec3 c=sfRamp(T,tint);
 // A faint glow over everything near the star, in the same ramp.
 c+=sfRamp(.5,tint)*exp(-max(r-limb,0.0)*6.0)*.05;
 fragColor=vec4(1.0-exp(-max(c,vec3(0.0))*1.15),1.0);
}

coarse.source:
// Per 2x2 block: the flame field at the block centre, for the main pass to interpolate. Blocks
// that no flame can reach (with margin) store nothing.
void vrchCoarse(in vec2 blockOrigin,in float blockSize,out vec4 value){
 vec2 fc=blockOrigin+.5*blockSize;
 vec2 p=(2.0*fc-iResolution.xy)/max(min(iResolution.x,iResolution.y),1.0);
 float aspect=iResolution.x/max(iResolution.y,1.0);
 float t=vrchPhase_speed();
 float limb=uParam_radius*.78;
 float r=length(p);
 float warp=.6+1.6*uParam_corona;
 float lp=smoothstep(.02,.2,uParam_left_y),rp=smoothstep(.02,.2,uParam_right_y);
 vec2 lh=vec2((uParam_left_x-.5)*2.0*min(aspect,1.6),(uParam_left_y-.5)*2.0);
 vec2 rh=vec2((uParam_right_x-.5)*2.0*min(aspect,1.6),(uParam_right_y-.5)*2.0);
 vec2 chest=vec2(0.0,-.35);
 vec2 d1=normalize(lh-chest+vec2(1e-4)),d2=normalize(rh-chest+vec2(1e-4));
 float surge=clamp(uParam_accent+max(uParam_motion-.3,0.0)*1.4,0.0,1.4);
 float h1=lp*(.1+.7*smoothstep(.35,.95,uParam_left_y))*uParam_lift;
 float h2=rp*(.1+.7*smoothstep(.35,.95,uParam_right_y))*uParam_lift;
 vec2 pd=p/max(r,1e-4);
 float g1=exp(-(1.0-dot(pd,d1))*14.0),g2=exp(-(1.0-dot(pd,d2))*14.0);
 float handH=h1*g1+h2*g2;
 float h=r-limb;
 float tall=sfV(pd*2.6+vec2(t*.11,-t*.07)),tall2=tall*tall;
 float H=.11+.06*sfV(pd*6.0+vec2(t*.2,0.0))+.32*tall2*tall+handH*(1.0+.6*surge)+.07*surge+limb*.1;
 value=vec4(0.0);
 if(r>limb*.5-.05&&h<H*1.83+.05){
  vec3 q=sfFireQ(pd,h,t,surge,warp);
  vec3 q2=q*2.03+vec3(1.7,9.2,3.1),q3=q2*2.03+vec3(1.7,9.2,3.1);
  float fs=.5*sfV3(q);fs+=.25*sfV3(q2);fs+=.125*sfV3(q3);
  value=vec4(fs*1.143,0.0,0.0,1.0);
 }
}
